using Finora.Application;namespace Finora.App;public sealed class LockViewModel:ViewModelBase{private readonly IAppLockService _lock;private readonly IAppSettingsService _settings;private string _pin="",_status="Enter your Finora PIN.";public LockViewModel(IAppLockService appLock,IAppSettingsService settings){_lock=appLock;_settings=settings;UnlockCommand=new AsyncCommand(UnlockAsync);UpdateStatus();}public string Pin{get=>_pin;set=>SetProperty(ref _pin,value);}public string Status{get=>_status;private set=>SetProperty(ref _status,value);}public System.Windows.Input.ICommand UnlockCommand{get;}private Task UnlockAsync()=>RunAsync(async()=>{if(_lock.RemainingLockout>TimeSpan.Zero){UpdateStatus();return;}if(await _lock.VerifyPinAsync(Pin)){Pin="";await Shell.Current.GoToAsync(_settings.OnboardingComplete?"//dashboard":"//onboarding");return;}Pin="";UpdateStatus();if(_lock.RemainingLockout==TimeSpan.Zero)Status="Incorrect PIN. Try again.";});private void UpdateStatus(){var l=_lock.RemainingLockout;Status=l>TimeSpan.Zero?$"Too many attempts. Try again in {Math.Ceiling(l.TotalMinutes)} minute(s).":"Enter your Finora PIN.";}}
